pytest.importorskip('piggy_bank.ui.filter_tools_rc', reason='UI not built, run ./driver.sh --build-gui')

from piggy_bank.aggr_stats import QW_AggrStats  # noqa: E402
from piggy_bank.filter_tools import QW_FilterTools  # noqa: E402
from piggy_bank.qw_misc import NumericTableWidgetItem, apply_color_scheme, ENV_COLOR_SCHEME, QW_ClassesPeriods  # noqa: E402


@pytest.fixture
def df():
    return pd.DataFrame({
        COL_DATE: ['2024-03-05', '2025-07-20'],
        COL_OUT: [-250.4, None],
        COL_IN: [None, 1200.9],
    })


@pytest.fixture
def df_classes():
    return pd.DataFrame({COL_CLASS: [CLASS_TODO, 'loan', 'food', 'food']})


def test_numeric_item_sorts_numerically(qtbot):
    assert NumericTableWidgetItem('9') < NumericTableWidgetItem('10')
    assert NumericTableWidgetItem('-100') < NumericTableWidgetItem('')  # empty counts as 0


def test_aggr_stats(qtbot):
    w = QW_AggrStats('All')
    qtbot.addWidget(w)

    w.update_stats([1.0, 2.0, 3.0, 10.0])

    assert w.qgb.title() == 'All'
    assert w.ql_entries.text().strip() == '4'
    assert (w.ql_min.text(), w.ql_max.text(), w.ql_sum.text()) == ('1', '10', '16')
    assert w.ql_median.text() == '2'  # 2.5 rounded half to even
    assert w.isEnabled()


@pytest.mark.parametrize('values, colour', [([-10.0, 5.0, -1.0], '#d62728'), ([10.0, -5.0, 1.0], '#2ca02c'),
                                             ([0.0], '#2ca02c')])
def test_aggr_stats_coloured(qtbot, values, colour):
    w = QW_AggrStats('All', coloured=True)
    qtbot.addWidget(w)

    w.update_stats(values)

    for label in (w.ql_sum, w.ql_median, w.ql_avg):
        assert colour in label.styleSheet()
    for label in (w.ql_entries, w.ql_min, w.ql_max, w.ql_std):
        assert label.styleSheet() == ''


def test_aggr_stats_coloured_mixed_signs(qtbot):
    w = QW_AggrStats('All', coloured=True)
    qtbot.addWidget(w)

    # sum 30 >= 0, median -1 < 0, mean 7.5 >= 0
    w.update_stats([-2.0, -1.0, -1.0, 34.0])

    assert '#2ca02c' in w.ql_sum.styleSheet()
    assert '#d62728' in w.ql_median.styleSheet()
    assert '#2ca02c' in w.ql_avg.styleSheet()


def test_aggr_stats_not_coloured_by_default(qtbot):
    w = QW_AggrStats('Out')
    qtbot.addWidget(w)

    w.update_stats([-10.0])

    assert all(label.styleSheet() == '' for label in (w.ql_sum, w.ql_median, w.ql_avg))


def test_aggr_stats_empty(qtbot):
    w = QW_AggrStats('Out')
    qtbot.addWidget(w)

    w.update_stats([])
    assert not w.isEnabled()

    w.update_stats([], hide_if_empty=True)
    assert w.isHidden()


def test_filter_tools_defaults_from_data(qtbot, df):
    ft = QW_FilterTools(df)
    qtbot.addWidget(ft)
    ft.setup_sliders(df)

    assert ft.qde_start.date().toString('yyyy-MM-dd') == '2024-03-05'
    assert ft.qde_end.date().toString('yyyy-MM-dd') == '2025-07-20'
    assert ft.qrs_out.value() == (-250, -250)
    assert ft.qrs_in.value() == (1200, 1200)


def test_filter_tools_class_checkboxes(qtbot, df, df_classes):
    ft = QW_FilterTools(df)
    qtbot.addWidget(ft)

    ft.setup_classes(df_classes)

    boxes = ft.class_checkboxes()
    assert list(boxes) == ['food', 'loan', CLASS_TODO]  # alphabetical, todo last
    assert [b.text() for b in boxes.values()] == ['food (2)', 'loan (1)', 'todo (1)']
    assert all(b.isChecked() and b.parent() is ft.saw_classes for b in boxes.values())
    assert ft.excluded_classes() == set()


def test_filter_tools_unchecking_a_class_filters(qtbot, df, df_classes):
    ft = QW_FilterTools(df)
    qtbot.addWidget(ft)
    ft.setup_classes(df_classes)

    with qtbot.waitSignal(ft.filters_updated, timeout=2000):
        ft.class_checkboxes()['loan'].click()
    assert ft.excluded_classes() == {'loan'}

    with qtbot.waitSignal(ft.filters_updated, timeout=2000):
        ft.class_checkboxes()['loan'].click()
    assert ft.excluded_classes() == set()


def test_filter_tools_classes_rebuild_keeps_unchecked(qtbot, df, df_classes):
    ft = QW_FilterTools(df)
    qtbot.addWidget(ft)
    ft.setup_classes(df_classes)
    ft.class_checkboxes()['loan'].setChecked(False)
    ft.class_checkboxes()['food'].setChecked(False)

    # e.g. after a reload: food is gone, a new class appears checked
    ft.setup_classes(pd.DataFrame({COL_CLASS: ['loan', 'rent', CLASS_TODO]}))

    assert list(ft.class_checkboxes()) == ['loan', 'rent', CLASS_TODO]
    assert ft.excluded_classes() == {'loan'}
    assert ft.qgl_classes.count() == 4  # 3 checkboxes and the spacer, nothing left over


def grid_cell(ft, qchk) -> tuple:
    row, col, _, _ = ft.qgl_classes.getItemPosition(ft.qgl_classes.indexOf(qchk))
    return row, col


def test_filter_tools_classes_fill_two_rows_by_column(qtbot, df):
    ft = QW_FilterTools(df)
    qtbot.addWidget(ft)

    ft.setup_classes(pd.DataFrame({COL_CLASS: ['a', 'b', 'c', 'd', 'e', CLASS_TODO]}))

    cells = {cls: grid_cell(ft, qchk) for cls, qchk in ft.class_checkboxes().items()}
    assert cells == {'a': (0, 0), 'b': (1, 0), 'c': (0, 1), 'd': (1, 1), 'e': (0, 2), CLASS_TODO: (1, 2)}


def test_filter_tools_classes_scroll_horizontally_only(qtbot, df):
    from PySide6.QtCore import Qt
    ft = QW_FilterTools(df)
    qtbot.addWidget(ft)
    ft.setup_classes(pd.DataFrame({COL_CLASS: [f'some long class name {i}' for i in range(30)]}))
    ft.show()
    qtbot.waitExposed(ft)

    sa = ft.sa_classes
    assert sa.verticalScrollBarPolicy() == Qt.ScrollBarPolicy.ScrollBarAlwaysOff
    assert sa.horizontalScrollBar().maximum() > 0  # 15 columns can't fit
    # Both rows are fully visible above the horizontal scroll bar
    assert sa.viewport().height() >= ft.saw_classes.height() >= ft.qgl_classes.sizeHint().height()


def test_filter_tools_dates_have_calendar_popup(qtbot, df):
    ft = QW_FilterTools(df)
    qtbot.addWidget(ft)

    assert ft.qde_start.calendarPopup() and ft.qde_end.calendarPopup()


def test_filter_tools_reset_restores_defaults_and_emits(qtbot, df, df_classes):
    ft = QW_FilterTools(df)
    qtbot.addWidget(ft)
    ft.setup_sliders(df)
    ft.setup_classes(df_classes)

    ft.qle_description.setText('pizza')
    ft.class_checkboxes()['food'].setChecked(False)
    ft.qchk_out.setChecked(False)

    with qtbot.waitSignal(ft.filters_updated, timeout=500):
        ft.qpb_reset.click()

    assert ft.qle_description.text() == ''
    assert ft.excluded_classes() == set()
    assert ft.qchk_out.isChecked() and ft.qrs_out.isEnabled()


def test_filter_tools_text_is_debounced(qtbot, df):
    ft = QW_FilterTools(df)
    qtbot.addWidget(ft)

    with qtbot.assertNotEmitted(ft.filters_updated, wait=200):
        ft.qle_description.setText('a')
    with qtbot.waitSignal(ft.filters_updated, timeout=2000):
        pass


@pytest.fixture
def restore_app_look(qapp):
    """apply_color_scheme() changes the shared QApplication: put its style, palette and scheme back."""
    from PySide6.QtCore import Qt
    style, palette = qapp.style().name(), qapp.palette()
    yield qapp
    qapp.setStyle(style)
    qapp.setPalette(palette)
    qapp.styleHints().setColorScheme(Qt.ColorScheme.Unknown)


@pytest.mark.parametrize('value', ['', None])
def test_color_scheme_unset_changes_nothing(restore_app_look, monkeypatch, value):
    qapp = restore_app_look
    monkeypatch.delenv(ENV_COLOR_SCHEME, raising=False)
    before = qapp.palette().window().color().name()
    assert apply_color_scheme(qapp, value) == ''
    assert qapp.palette().window().color().name() == before


def test_color_scheme_dark_from_env(restore_app_look, monkeypatch):
    qapp = restore_app_look
    monkeypatch.setenv(ENV_COLOR_SCHEME, ' Dark ')
    applied = apply_color_scheme(qapp)
    assert applied in ('dark', 'dark-fusion')
    if applied == 'dark-fusion':
        assert qapp.style().name() == 'fusion'
    assert qapp.palette().window().color().lightness() < 100
    assert qapp.palette().text().color().lightness() > 200


def test_color_scheme_invalid_is_ignored(restore_app_look):
    assert apply_color_scheme(restore_app_look, 'purple') == ''


def periods_column(w, header) -> list:
    table = w.qtw_periods
    col = next(c for c in range(table.columnCount()) if table.horizontalHeaderItem(c).text() == header)
    return [table.item(r, col).text() for r in range(table.rowCount())]


def test_classes_periods_table(qtbot):
    w = QW_ClassesPeriods()
    qtbot.addWidget(w)
    df = pd.DataFrame({COL_DATE: ['2024-12-31', '2025-01-02', '2025-01-10'],
                       COL_OUT: [-20.0, -10.0, 0.0], COL_IN: [0.0, 0.0, 100.0]})

    w.qcb_periods_time.setCurrentText('Monthly')
    w.update_periods(df)
    # Newest first
    assert periods_column(w, 'Date') == ['2025-01', '2024-12']
    assert periods_column(w, 'Out') == ['-10', '-20']
    assert periods_column(w, 'In') == ['100', '0']
    assert periods_column(w, 'Sum') == ['90', '-20']
    assert periods_column(w, 'Entries') == ['2', '1']
    assert w.qtw_periods.item(0, 3).foreground().color().name() == '#2ca02c'
    assert w.qtw_periods.item(1, 3).foreground().color().name() == '#d62728'

    # Changing the time frame re-renders from the stored data. Tue 31 Dec and Thu 2 Jan share the week of Mon 30 Dec
    w.qcb_periods_time.setCurrentText('Weekly')
    assert periods_column(w, 'Date') == ['2025-01-06', '2024-12-30']
    w.qcb_periods_time.setCurrentText('Yearly')
    assert periods_column(w, 'Date') == ['2025', '2024']

    w.update_periods(df.iloc[0:0])
    assert w.qtw_periods.rowCount() == 0
